    interpretation: "大礼议虽以礼名始，却以权力终。杨廷和欲以「继嗣」将新君纳入孝宗—武宗的统嗣链条，从而以内阁主导的礼法体系约束皇权；世宗则借「继统」重树皇考正统，确立统自朕出的独断之局。世宗先逐首辅，再杖群臣，终颁《明伦大典》，使议礼新贵以末秩致位宰辅，内阁由制衡之府降为承顺之地。此役之后，士大夫敢谏之风摧折殆尽，科道钳口，迎合竞进者日众，为后来严嵩长期窃权铺平了道路。嘉靖一朝西苑斋醮、不视朝政而大权独揽的政治格局，正肇端于左顺门的杖下；明代皇权与士大夫共治的平衡，亦自此倾斜难复。",
