    interpretation: "萨尔浒之战历来被视为中国军事史上「集中兵力、各个击破」的经典战例，其成败根源远不止战场用兵。表面看，明军败于分兵四路、将帅失和；深层看，败于一个老大帝国的体制性衰敝：财政上，万历三大征耗尽太仓，辽饷加派激成民怨；政治上，党争与催战压倒专业判断，杨镐明知准备未就，仍被严旨逼上战场；军事上，卫所制度崩坏，临时拼凑的各省客兵互不统属、号令不一。反观后金，八旗制度军民合一，牛录、固山编制严整，贝勒子侄冲锋在前，赏罚分明，机动性远超明军车步骑混杂的联军。努尔哈赤「凭尔几路来，我只一路去」之策，正是建立在对自身机动优势和对手指挥僵化的清醒判断之上。此役证明：决定战争胜负的不仅是兵力多寡，更是指挥、情报与机动力。明朝以举国之兵而败于一隅，根源正在于制度的腐朽与决策的昏聩。",
