    interpretation: "甲申之变的深层逻辑，在于明朝财政与军事体系的双重破产。三饷加派把辽东战费转嫁给最脆弱的小农，天灾与苛税相乘，使流民转化为席卷中原的农民战争；松锦、潼关两役丧尽九边精锐，明朝事实上已内囊尽上。崇祯帝勤政而刚愎，用人多疑，举措屡更，南迁之议为群臣所误，遂致君死社稷。大顺军虽以「不纳粮」得饥民之心，入京后却拷掠勋戚官僚，未能与士绅集团合作，逼反吴三桂，致有山海关之败。清朝以关外小部入主中原，藉吴三桂开关之机，一战而定大局，入京后迅速收揽人心、承明制而纠其弊。甲申之后，南明仅余偏安，天下由乱入治，王朝更替与社会结构的深层变动遂告完成。",
