    interpretation: "曹石之变，论其远因，在夺门之立本非正途。景泰帝病亟，英宗复位不过迟早之事，石、曹诸人借机邀功，以兵闯宫门，名为迎复，实为据功。论其近因，则功臣恃功骄横，侵夺皇权：石亨一门、曹氏诸侄分据将相，卖官鬻爵，台谏不敢言，祸机已伏。石亨先败，曹吉祥不自安，遂铤而走险，终至族灭。此案之平，使京营兵权尽归天子，夺门冒滥之赏尽行裁革，李贤等阁臣得行其志，天顺末年政治渐趋清明。然宦官提督京营之制未废，明代宦祸之根仍在，至正德、天启而愈烈，则非英宗所能及见矣。",
