          "石氏既灭，曹吉祥、曹钦叔侄益惧，阴畜死士，预为自全之计。天顺五年（1461年）七月，曹吉祥与其侄曹钦拥兵作乱。曹钦率番将伯颜也先等夜攻东长安门及东华门，杀都御史寇深；恭顺侯吴瑾率众力战，死之。怀宁伯孙镗闻变，仓促集兵，会诸将巷战，乱兵遂溃。曹钦败走无路，投井自杀；曹吉祥被执，磔于市，夷其族。曹吉祥之乱既平，距夺门之变不过四年，首恶尽数覆亡。",
