    interpretation: "夺门之变名为「迎驾」，实为篡逆。其根源不在一日之谋，而在皇统的先天裂痕：土木之变后，于谦等拥立景泰，本为社稷计，然太上皇在位、南宫幽居，使皇权始终存在两个合法性的中心。景泰帝易储不成、储位悬空，又值重病，皇权空缺自然引来政治投机。石亨、徐有贞、曹吉祥以毁墙之勇博取富贵，复以「意欲」二字杀于谦——杀于谦并非因其真有迎立之谋，而是不杀则夺门无名、不杀则功臣不安。于谦之一死，实为皇位更替必须付出的政治代价。然以诬杀柱石始者，必以同党倾覆终：石亨骄横而败，曹吉祥恃兵而灭，四年之内首恶尽除，恰证明以贪功侥幸得天下者，终不能以贪功侥幸守之。英宗晚年渐悟其冤，宪宗成化间为之平反，而忠魂已逝，国本已伤。",
