          "嘉靖二十九年（1550年）春，俺答复大举攻掠大同，兵锋甚锐。时仇鸾以贿严嵩得宣大总兵之职，本不知兵，闻警惶惧无策，未敢出一兵迎敌。俺答遣其子托克托等至大同，扬言将深入内地，以兵临之，名为通好，实为示威。仇鸾畏葸，不知所出，密遣家丁持重金往赂俺答，求其移师他往，勿犯大同。俺答既受金，许之，遂舍大同而东，转犯蓟镇。仇鸾赂敌求免，反以却敌报功，边臣效尤，各以金帛结欢于敌，边防之坏，至此而极。",
          "俺答既舍大同，遂率所部精骑东进，径趋古北口。古北口为京师东北门户，依山凭险，向称天险，而蓟镇兵备久弛，守备单弱，边墙多已倾颓，守军不满额数。俺答督兵猛攻，总兵王汝孝率部迎击，军大溃，死者籍籍，余众披靡四散，关隘遂失。俺答长驱直入，经石匣营直抵通州，遂渡白河而西，沿途焚掠，烟尘蔽天，直薄北京城下。京师自正统「土木之变」后百余年间，未有胡骑临城之事，举朝震恐，中外大骇，人心大乱。",
          "八月庚戌，俺答兵临北京城下，驻营安定门外，游骑四出，德胜、安定、东直诸门皆闭。警报日至，明世宗朱厚熜大惊，急调诸道兵马勤王，诏下七日内。辽东、宣府、大同、山西、延绥及京营兵陆续至者十万，乃以仇鸾为平虏大将军，统摄诸军，赐以金印，俾专征伐。京师戒严，九门尽闭，城中居民惊惶奔走，米价腾贵，朝臣亦莫知所措。世宗召见群臣，问退敌方略，廷议纷然，或言战，或言守，久而不决，终无定算。"
