    interpretation: "庚戌之变之根源，不在俺答之强，而在明朝之弱。俺答求贡二十年，其志在互市，非在城池土地，明廷若早开互市，边患可消于未形。然世宗执迷于「土木之变」之鉴，视通贡为屈辱，拒之益坚，迫之愈急，终至兵临城下，城下之盟，辱更甚焉。严嵩以「寇饱自飏去」之说，行苟且偷安之实，畏战而不备战，误国而能自全；丁汝夔受其指使，代受其过，临刑一呼，道尽权臣误国之痛。仇鸾以赂敌冒功，位极人臣，旋即败亡，可见赏罚倒置，将士寒心。此役之后，明廷虽开马市，然勉强从事，旋开旋罢，边患终不可息，直至隆庆和议，始得久安。要之，庚戌之变暴露明朝中期军备废弛、朝政腐败之弊，亦揭示通贡互市为不可阻挡之势，逆之则兵连祸结，顺之则北疆得安。",
