          "万历三十一年（1603）十一月，妖书案起。有《续忧危竑议》传播宫禁内外，言郑贵妃欲废太子而立福王。神宗震怒，令东厂、锦衣卫大索主使，株连朝野。大学士沈一贯欲借机倾陷沈鲤、郭正域，事虽得白，朝士重足而立。妖书真犯终未获，株连甚众，国本余波震荡朝局。万历四十二年（1614）三月，福王朱常洵就藩洛阳，赐庄田二万顷，并予盐引，所赐之厚冠于诸藩，群臣争之不能得。",
          "万历四十三年（1615）五月初四，有张差者持木梃闯入慈庆宫，击伤守门内官，梃击案起。朝议汹汹，皆疑郑贵妃、福王主使，欲借此动摇储位。神宗不愿深究，命会审，张差磔于市，涉案内官庞保、刘成秘密处死，真相益不可知。其后泰昌元年（1620）朱常洛即位仅一月而暴卒，红丸案起；继以移宫案，群臣拥皇长子朱由校即位，逼迁李选侍。梃击、红丸、移宫三大案，皆国本之争之余波。《明史·神宗本纪》论曰「论者谓明之亡，实亡于神宗」，此争实为明室由盛转衰之枢纽。"
