    interpretation: "国本之争表面为争储位，实为皇权与文官集团之制度性对抗。神宗虽握乾纲，却无法公然违背「有嫡立嫡、无嫡立长」之祖训，乃以并封、迁延、留中诸术与臣周旋，终不能抗天下公议。文官集团以宗法为武器，以清议为后盾，前仆后继，百折不挠，士风因之激昂，门户因之分明。争之愈烈，则神宗愈怠；神宗愈怠，则国事愈坏。十五年空耗，边备、财政、吏治皆受其累，至万历四十六年（1618）辽事起而国力已竭。东林党议由此发端，三案继之，启、祯两朝犹其余祸。故《明史》论「明之亡，实亡于神宗」，国本之争实其枢纽：一人之私情，牵动一朝之治乱，明室由盛转衰，此其关键。",
