    interpretation: "郭桓案之发生，根源在于朱元璋对官僚系统根深蒂固的不信任，以及他以运动式大狱替代常规治理的施政逻辑。洪武制度不可谓不密：赋役黄册登户口田土，粮长催征税粮，仓有专员，账账相稽；但制度运行终须依赖人，而朱元璋相信乱世初定、人心未化，非严刑无以儆贪。空印案未竟其功，遂有郭桓案之穷治；穷治又不止于刑杀，更在追赃——追赃七百万石、寄借遍天下，实则是以追赔为手段，将打击面扩及寄藏赃物的中产之家与江南官绅，把朝廷的财政汲取力度推向极端。此案因此具有双重面相：既是吏治整肃的巅峰，也是皇权对官绅社会的一次大规模震慑。它换来了一时之清，也付出了人才摧折、官员因循、吏治深层积弊并未根绝的代价。明清两代重惩贪墨的法律传统，其来有自；而运动式治理与常法制度之间的张力，在此案中已显露无遗。",
