    interpretation: "红丸案之本质，不在红丸本身，而在晚明皇权交接的制度失序。神宗怠政近三十年，缺官不补，内阁与司礼监的制衡渐失；又因国本之争，东宫势弱，太子身边无有力辅翼，一旦继位，宫中进药、侍寝诸事皆操于宦官与宠妃之手，外朝莫能究诘。李可灼以鸿胪寺丞末秩，遽进御药，方从哲不能裁制，崔文升掌御药房而无医官之责，皆暴露出明代御药制度与宫廷仪制在权力交接之际的巨大漏洞。光宗之死，究竟死于虚损耗竭，抑或死于药误，正史终无明文，然前后二药相因，遂成千古疑案。此后东林、阉党各以三案为兵器，翻覆之间，朝堂只剩门户，不见国是。故三案虽起于宫闱，其祸实延于天下：天启朝之缇骑四出、正人碎骨，崇祯朝之猜忌相寻、再翻再覆，皆与此案之悬而未决、论而不决深相关联。",
