    interpretation: "弘治中兴之实质，乃守成之君以个人勤勉矫前朝之弊。孝宗幼年身处宫闱险境，母死身危，故即位后痛恨佞幸、体恤下情，此其动力；斥传奉、逐僧道、复经筵午朝、广开言路，此其纲领；任贤使能、和衷共济，此其枝干。然其治终赖君主一身之克制，未尝稍触皇庄、宗禄、中旨传奉之根本：传奉官虽罢，而内廷干预铨选之门未绝；皇庄虽戢，而宗室赐田日增。故孝宗崩未数年，正德朝刘瑾等八虎用事，传奉再兴，朝纲顿乱，弘治积蓄一朝耗尽。可见其治乃人治之极致，而非制度之更始。史家并称仁宣，正以其同为贤君守成之治；然仁宣有制度之遗，弘治则仅余风范，此其异也。",
