          "清廉如济宁知府方克勤，亦死于是狱。方克勤，字去矜，浙江宁海人，洪武四年除济宁知府。为治以德化为先，自奉简素，三年之中，济宁户口自三万增至六万有奇，一郡大治，百姓歌之。洪武八年，为府吏程贡所诬，左迁江浦。九年空印事发，克勤复以属吏牵连下狱，论死。其子方孝孺，时年二十，少从宋濂学，扶丧归葬，作《先府君行状》，备述其父之廉介与是狱之冤，字字血泪，为后世留下此案最为详赡的记述。"
