          "方克勤既死，天下冤之，而朝堂无敢言者。宁海郑士利，字好义，与方克勤同邑。其兄郑士元，洪武四年以秀才举，授湖广按察使佥事，廉直有吏干。九年空印事发，士元以主印之故系狱，坐死。士利闻之，叹曰：「兄死，我何生为！」度帝怒方盛，谏必不纳，故迟之；及岁余，乃上书数千言，讼空印之冤。知此书一上，身家性命悬于一线，而慨然为之不悔。其书上论国法，下陈民情，辞切而理直。",
          "其书大旨有四：一曰空印之习，「元时故有之，未尝为弊」，今日沿而行之，非明知故犯；二曰国家治罪，必先明著律令，使天下知所避就，今律无空印之条，骤加以死罪，是罔民也；三曰朝廷重空印之罪，则奸吏得以持此构陷良吏，一郡一邑之长，皆可指为空印而尽诛之；四曰主印者死、佐贰者戍，同罪而异刑，亦非法之平。盖以为先王制法，必先晓谕天下，使吏民知所避，然后罪之，未有法未立而先诛者也。四者皆切中当时之弊，虽不能回帝意，而其理自不可没。",
          "「书入，上怒，下士利狱，戍江浦。」朱元璋见书，不纳其言，反疑书生受人指使，欲为空印诸囚开脱，怒益甚，遂并士利治之。士利既戍江浦，其兄士元亦死于狱。方克勤已死，郑士元复殁，狱既不可挽回，而谏者又获重谴，自是以后，朝堂之上无敢言空印之事者，虽台谏之臣亦钳口结舌。一书之难回，岂独士利一人之厄，实天下言路之厄也。"
