          "朱元璋惩元季吏治纵弛，特好用重典。洪武十八年，颁《大诰》于天下，采辑官民过犯之尤者，昭示中外；十九年、二十年复有《续编》《三编》之颁，皆以严刑峻法绳天下之吏。其意本在惩贪剔蠹、澄清吏治，然空印案所开之端，乃以猜忌成狱、以积习定罪，律令未立而诛戮已行，与《大诰》之旨相表里。明代胥吏不得出身、士大夫轻视吏职，论者每追溯于此案；重典之下，官吏苟且畏缩，法立而弊生，亦其一失。",
