    interpretation: "空印案之酷，不在于刑之重，而在于罪与法不相副。空白文册本身不过是一种规避制度成本的变通：地方官吏千里赍册入京，若遭户部驳正，重造须重新盖印，往返动辄数月，故预盖空印备改。此法元时已有，户部默许，上下习为常式，并无侵盗实迹。朱元璋不问有无贪腐之情，但以「欺罔」二字定罪，主印者尽诛，佐贰者杖戍，故后世争议最大、起因最暧昧。其深层逻辑，在于朱元璋以一人之智察驭天下，以猜忌之心行重典之治：凡律所未及者，即以意断之；凡习所相沿者，即以法绳之。此狱一开，洪武一朝遂以严刑峻法为常：十三年诛胡惟庸，十八年治郭桓，二十六年诛蓝玉，株连动以万计。其效在肃清吏治于一时，其弊在使有司苟且畏缩、士大夫以从政为讳。明代二百余年，官吏分途、文法日繁，论者每追溯于此案。",
