          "蓝玉，安徽定远人，开平王常遇春之妻弟。少年时即隶常遇春帐下，数从征伐，临阵勇敢，所向皆捷，常遇春屡于太祖前称其骁勇。《明史·蓝玉传》载其仪状云：「玉长身赪面，饶勇略，有大将才。」洪武十四年（1381年），太祖命颍川侯傅友德为征南将军，蓝玉与西平侯沐英并为副将军，率步骑三十万征云南。师至，元梁王把匝剌瓦尔密败死，云南平定。蓝玉功居最，以功擢永昌侯，予世券，岁禄二千五百石。自此威名远播，太祖亦数加奖谕，倚为腹心。",
          "洪武二十一年（1388年）春，太祖拜蓝玉为征虏大将军，总兵北征。时元主脱古思帖木儿遁居漠北，部众犹存，屡为边患。蓝玉率十五万大军出大宁，进至庆州，侦知元主驻牧于捕鱼儿海，乃督军衔枚夜行，直掩其营。会大风扬沙，昼晦，元军不设备，明军猝至，大破之。是役获元主次子地保奴、妃主以下数万人，马驼牛羊十五万余，辎重无算。北元经此一败，部众星散，由此一蹶不振。捷报至京，太祖大喜，下诏褒美，以汉卫青、唐李靖比之，赏赐甚厚。",
          "师还论功，蓝玉威望达于顶点，一时武臣之中无出其右者。太祖初欲封以梁国公，酬其扫荡漠北之首功；然蓝玉于还军途中私通元主之妃，元妃惭惧自杀，太祖闻之大怒，切责蓝玉，遂改封凉国公。册封之际，太祖特命将其罪愆镌刻于铁券之上，以示惩戒。蓝玉以盖世之功仅得凉国公之爵，心怏怏不乐，然太祖尚念其勇略，仍委以兵权，俾总师干。君臣嫌隙自此而萌，而蓝玉不以为戒，骄蹇益甚，祸胎已暗结于此矣。"
