          "洪武三十一年（1398年）太祖驾崩，皇太孙朱允炆即位，明年改元建文。建文朝廷欲行削藩，燕王朱棣遂于建文元年（1399年）七月起兵靖难。其时开国宿将凋零殆尽，建文帝环顾朝堂，竟无可任之大将，所用者李景隆之辈，皆纨绔无能之徒，丧师辱国。南军虽众，不敌燕藩一隅，建文四年（1402年）京师陷落，帝不知所终，朱棣遂入承大统。后人推原祸本，皆谓胡蓝之狱自毁长城，使建文之世无将可用，蓝玉案之余波，竟倾覆一帝之天下。"
