    interpretation: "蓝玉案之本质，是皇权与开国武勋集团之总决战。明初定鼎，功臣宿将手握重兵，太祖初犹倚之，及天下大定，则猜忌日深。胡惟庸案废丞相，文臣之权既削，武将之患自当次第除之。洪武二十五年太子朱标之死，实为蓝玉案之直接诱因：朱标仁厚，与蓝玉有姻亲之谊，足可镇抚；朱标既没，皇太孙朱允炆年方十六，以蓝玉之桀骜，断非幼主所能驭。太祖宁负功臣，不肯负子孙，遂兴一狱，尽诛一公、十三侯、二伯，株连一万五千余人。然太祖之失亦在于此：武勋既尽，藩王代兴，建文朝无将可用，靖难之师遂长驱入京。有明一代，兵权归之兵部，武将位在文臣之下，重文轻武之局由此定，而胡蓝之狱，实其枢机也。",
