          "崇祯十六年（1643）春，李自成攻克襄阳，改名襄京，称「新顺王」，初建政权：设丞相、六政府侍郎、从事等官，以牛金星为谋主，宋献策为军师；又设五军都督府统领兵马，命将镇守各地。同时革除明末苛政，宣布「三年不征，一民不杀」，民间稍安。是时大顺已据有荆襄、河南大部。明廷以孙传庭为兵部尚书督师，出潼关东征。李自成采纳诱敌深入之策，以主力伏于郏县以南，别遣权将军刘宗敏率轻骑断其粮道。",
          "崇祯十六年九月，孙传庭率师至汝州，粮道被断，军中大乱，被迫分兵撤退。李自成乘势追击，大破明军，孙传庭部全军覆没，孙传庭战死于潼关，总兵白广恩、陈永福等或死或降。此即汝州之战，明廷最后一支精锐之师就此覆灭。《明史·孙传庭传》论曰：「传庭死而明亡矣。」李自成乘胜破潼关，于十月进据西安，收编明军，开仓赈贫，秦陇悉下，声势大振。汝州之战实为大顺立国的关键一战。",
          "崇祯十七年（1644）正月，李自成在西安建国，国号「大顺」，改元「永昌」，改西安为长安，定官制，设内阁六部，开科举，铸「永昌通宝」钱；又定军制，以权将军刘宗敏，制将军李过、高一功、刘芳亮等分统各军。二月，李自成率大军渡黄河入山西，破宁武关，总兵周遇吉力战殉国；大同总兵姜瓖、宣府总兵唐通先后来降。三月十五日，大顺军入居庸关；十七日，兵临北京城下。明廷征天下勤王兵，无一至者。"
