          "崇祯十七年三月十八日，大顺军攻城，守城太监开门迎降，京师外城陷。崇祯帝鸣钟召集百官，无一至者；十九日拂晓，帝登煤山（今景山），自缢于古槐，衣带留书：「朕自去冠冕，任贼分裂朕尸，勿伤百姓一人。」大顺军入紫禁城，北京易主，共传十六帝、二百七十六年的明朝，至此灭亡。李自成进城后，下令安抚百姓，禁杀掠，市肆如故；又礼葬崇祯帝，示天下以宽。然大顺政权入京之后，迅速由盛转衰。",
