    interpretation: "明末农民战争之烈，根源在财政与军事的双重崩溃。万历末年辽事起，三饷加派把战争成本悉数转嫁于贫民；宗室人口至崇祯时已数十万，禄米成为财政重负；而西北连岁旱蝗，官府不赈反征，饥民唯有死中求生。李自成以「不纳粮」为号召，深得民心，正因他点破了加派与苛政这一时弊。但流民政权长于破坏而短于建设：「不纳粮」使军队无饷可恃，入京后以追赃助饷代替正供，拷掠缙绅，把官僚士绅推向敌对阵营；将帅骤富骤骄，军纪随之瓦解。山海关之败，暴露其既未安抚吴三桂、又未防备清军的战略失算。李自成可以摧毁旧秩序，却未能建立新秩序；其覆亡之后，清军入关，南明残局延续，中国历史由此转入新轨。",
