    interpretation: "隆庆和议之所以能成，在于其直抵明蒙冲突的经济根源。蒙古草原单一游牧经济，不能自给粮食、布匹与铁器；俺答求贡，本质是求生计所需，而非贪图虚名。明朝以封锁应之，迫其以武力抄掠，代价反更惨烈。高拱、张居正与王崇古、方逢时之卓识，在于识破「封锁—抄掠—再封锁」的死循环，以封王给其名、互市给其利，名实双至，化敌为藩。较之汉唐和亲之屈、宋代岁币之辱，封贡体系以经济互赖替代军事对抗，明朝所费有限而收效长远。其成功亦赖阁臣与边臣同心、穆宗奋断，否则书生横议，足以坏事。然和议之可行，亦因俺答老而厌兵、部众思安，此乃时势使然。张居正后日整顿财政、充实国库，正得此数十年边宁之赐。和议证明：处理边疆民族关系，通商互市、以利养和，远胜于闭关绝市、以兵止兵，此为明朝边疆治理最成功之实践。",
