          "二十六日，后金倾力再攻，战士皆顶盔贯甲，负板掘城，城上箭矢铅丸如雨。袁崇焕见情势危急，乃刺血为书，以激将士，将士皆请效死。总兵满桂率死士出城接战，往来冲杀；祖大寿等督兵于城上，以佛郎机、鸟枪连环轰放。后金兵虽悍勇，然于城下暴露于炮火之中，进退失据，伤亡渐重，渐惮红夷炮之威，不敢复近城垣。鏖战竟日，后金军连攻三日而不能克，锐气大挫，尸骸狼藉于城濠之间。",
          "鏖战至二十六日暮，后金军于宁远城下伤亡枕藉，死者弃于城濠，伤者蹒跚而返，努尔哈赤知城不可下，遂下令撤围。清官书于此次败绩并不回避，记其「自二十五岁征伐以来，战无不胜，攻无不克，惟宁远一城不下，遂大怀忿恨而回」。后金大军解围之后，不甘空返，转师东向，以骑兵踏冰攻觉华岛，焚毁水师粮储。宁远之围遂解。是役自二十四日至二十六日，凡三日，明军以不满两万之众，拒后金号称十三万之师，自萨尔浒丧师以来，此为明军对后金作战中罕见之大捷。"
