          "后金兵既登岛，纵火焚仓厫、毁水师。觉华岛所储粮料、所泊舟船，多为灰烬，水师将士死伤甚众，金冠等战死，岛上屯民亦多遭屠戮。此役明军损失之重，几与宁远守城之功相抵。是以论者谓宁远之捷实为胜负相参：城守则全胜，海援则大败。明廷奏报亦不讳言损伤，明熹宗谕旨中于斩获之外，亦言兵将之失。觉华岛既失，宁远一城益形孤立，然山海关外，自此坚守之志愈坚。",
