    interpretation: "宁远大捷之胜，首在火器与城守之合。红夷大炮射远力猛，使后金步骑不能近城；坚城深濠，又使骑射野战之长无所施。此役证明，明军若守御有方、将帅用命，足以抵挡后金主力。然战术之胜不能掩盖战略之困：觉华岛覆没，粮船尽失，明军辽西水师一蹶不振；高第尽撤关外，使宁远孤立无援，幸而未陷，实赖袁崇焕一人之坚与满桂等将士之勇。此役之后，努尔哈赤怀忿而死，后金权力更迭，皇太极嗣位后改变策略，先征朝鲜、蒙古，再图辽西，明廷仅恃宁远、锦州一线，终至松锦覆军。就全局而言，宁远之捷延缓后金西进步伐，维系辽西对峙二十余年，然明之国困于党争与财政，辽饷岁岁增加，终成压垮明朝之一端。宁远一城之得失，亦明清兴替之缩影。",
