          "七月二十日，官军薄南昌城下。贼守将闭门拒守，伍文定身先士卒，亲冒矢石，先登陷阵，诸军继之，呼声震天，遂克复南昌。是役获宜春王朱拱樤及宸濠世子、郡王、宫眷数百人，收缴宁府符印、册宝、军资器械无算。守仁入城，安抚军民，籍没贼党，诛抗命拒战者若干人，胁从者悉释不问，城中秩序井然，市不易肆。自誓师至克城，仅三日耳，宸濠经营十余年之巢穴，一朝而覆，贼闻之胆落。",
          "宸濠在安庆闻南昌失守，恐根本动摇，军心大乱，遂弃安庆围，悉众回师，并九江、南康之兵，号十万众，蔽江而下，欲复南昌。守仁闻报，不退不守，率师迎击于鄱阳湖，以逸待劳。诸将或谓贼众我寡，宜固守南昌，待其师老兵疲而击之。守仁曰：贼闻巢穴已失，进无所攻，退无所归，军心必乱，当及其未定而击之；若纵之登岸，则江西糜烂，不可收拾。遂誓师出湖，列舟以待，决战于鄱阳湖上。"
