          "七月二十六日，宸濠联舟为阵，进退失灵，此实兵家大忌。守仁察其弊，命以小舟载薪刍膏油，乘风纵火，火烈风急，贼舟尽焚，烟焰蔽天，湖水为赤。官军乘势四面蹙之，贼众大溃，赴水死者万计。宸濠与其世子、郡王及谋主李士实、刘养正等皆就擒，其妃娄氏投水而死。自六月十四日举事至就擒，仅四十三日，世称三十五日平叛。江西全省悉平，捷报传布，远近欢腾，而朝局之争，方兴未已。",
