    interpretation: "宁王之乱，前后不过四十三日，而其关涉者大。其一，此役暴露明代宗藩之痼疾。自靖难之后，朝廷削夺藩权，然宁藩以重贿内廷，得以复置护卫、广蓄死士，可见贿结近幸、藩禁松弛，方是祸根；孙燧七疏告变而不达天听，更见正德朝纲纪之坏。其二，王守仁以文臣巡抚之身，无重兵、无诏命，闻变即奋，间道奔走，纠合义旅，转战月余而灭倾国之贼，此明代文臣统兵制胜之巅峰，亦心学「知行合一」最著名的事功印证——临危不惧、当机立断、知即能行，非空谈心性者所能及。其三，平叛之后，武宗挟私南征，嬖幸构陷，功臣几不免，折射正德末年皇权与文官集团之深刻矛盾。要之，一役也，而制度之弊、学术之用、朝局之险，皆具见于此矣。",
