    interpretation: "三大征是明朝军事史上的最后辉煌，也是其财政崩溃的起点。三役之中，明军将士用命，李如松、刘綎、麻贵、陈璘等皆一时名将，平叛、御倭、改土归流，武功之盛为嘉靖以来所未见。然三战皆捷的背后，是张居正改革积累的家底被迅速消耗：太仓存银由四百万两以上一空，户部岁入不敷岁出，朝廷遂开矿税以敛财，加派以筹饷，万民困于诛求，国本因之动摇。更可叹者，三役虽胜，皆未根除后患：丰臣秀吉死后日本息兵，然辽东建州女真乘明朝耗财竭力之时悄然崛起，终成亡明之大患。神宗怠于理政，奏疏留中，缺官不补，上下否隔，加以国本之争、党争纷起，朝局日非。《明史·神宗本纪》叹曰「论者谓明之亡，实亡于神宗」，正谓三大征之胜徒见其表，而国库空虚、民力凋敝、边患东起，已伏明亡之机。",
