    interpretation: "移宫案之本质，是皇权交接失序下的一场宫廷政变。明制新君当居乾清宫即位，而光宗暴崩、未留遗诏，李选侍遂以抚育皇长子为唯一资本，盘踞正寝；其所争者表面是皇贵妃、太后尊号，实则垂帘摄政之权。杨涟、左光斗以小臣奋身，王安为内廷内应，刘一燝等重臣断后，三日之内定夺大计，其果敢为史家所称。然此役全恃非常之举：外朝与内廷联手逼宫，虽扶正纲纪，亦开臣下以道德名分干政、以拥立之功邀权之端。东林以移宫自矜，盈朝而不悟盈满之忌；阉党借三案反噬，修《三朝要典》翻案，门户之争至崇祯朝而不能息。论者谓：移宫功臣之节诚可嘉，而天启一朝东林与阉党你死我活之局，实胎息于此三日内也。",
