        paragraphs: [
          "永乐十九年（1421）正月初一，新建成的奉天殿彩焕云甍，朱棣御殿受朝贺、颁大赦，下诏改北京为京师、南京为留都，正式完成迁都。诏书明定两京并立之制：北京六部、都察院等中央官署悉移驻新都；南京仍存六部、都察院、五府等一套机构，设守备、参赞机务等官掌理，惟以北京为政令所出。是日百官上表称贺，四夷朝使云集，礼成而大赦，天下咸知国都已定于北。",
          "迁都甫定百日，灾变骤生。永乐十九年四月初八庚子，京师雷雨大作，雷火自奉天殿起，延烧华盖、谨身二殿，复及奉天门与两廊，新宫精华顷刻化为焦土。《明史·成祖本纪》记：「奉天、华盖、谨身三殿灾。」自古宫阙灾异多视为上天示警，况三大殿乃新朝正衙、迁都之象征；朱棣闻变震惧，罢朝数日，下诏求直言，令文武群臣各陈阙失，朝局为之一震。",
          "诏下之后，朝臣借天变上书，多言迁都非宜、营建劳民。翰林院侍读邹缉、李时勉等上疏，陈营建以来民不堪命之状，词旨切直；主事萧仪论迁都之失尤切，以为轻弃太祖定鼎之地，触怒朱棣，下狱而死。朱棣以诸臣借天变谤讪，怒不可遏，然亦不得不有所修省，申明迁都本意在控御四夷、统制天下。三大殿虽毁，朱棣始终未下复都南京之诏，迁都之议遂在高压之下暂告平息。"
        ]
