      {
        heading: "重修三殿，定鼎北疆",
        paragraphs: [
          "三大殿灾后，宫阙残破，朱棣以国力艰难，未即重建，仅葺奉天门以听政。永乐二十二年（1424），朱棣北征返程卒于榆木川；仁宗朱高炽即位，一度有还都南京之议，洪熙元年（1425）诏令北京诸司仍称「行在」，欲择日南还，然未及行而崩。宣宗朱瞻基继立，仍视北京为根本，还都之议遂寝。正统五年（1440）二月，重建三殿两宫；六年（1441）九月告成，十一月以成告天地、宗庙、社稷，重建三大殿及两宫告成，定都北京成定局。",
          "定都北京后，为支撑京师与边防，漕粮、重兵随之北移。明代每年自江南漕运粮食约三四百万石入京、通两仓，供皇室、百官、京军之需；京师驻扎五军、三千、神机三大营，合操军士数十万。皇帝驻跸北疆，直接节制九边，形成「天子守国门」的格局，长城沿线由此成为重兵密布的防御纵深。然京师距塞外不过数日之程，一旦边警，天子首当其冲；正统十四年（1449）土木之变，英宗蒙尘，瓦剌兵临北京，几致倾覆，幸赖于谦力战解围。",
          "国都北移，朝廷物资仰给江南，漕运耗费成为经久负担：岁漕数百万石，加上造船、疏河、军运之费，国计民生为之牵动，终明之世，省漕、复都之议不绝。然大运河将江南财赋与北方政治中心贯通，沿线临清、济宁、淮安等城市随之繁盛，南北经济整合反因迁都而加深。此后五百余年，北京始终是中国的政治中心：明清两代、民国初年皆都于此；紫禁城、天坛与中轴线至今仍塑造着这座城市的面貌。"
        ]
      }
