    interpretation: "永乐迁都，是帝王之私与王朝战略的合流。朱棣以藩王入继大统，根基在北，南京建文旧臣盘根错节，还居旧藩势所必然；而元亡之后蒙古诸部仍为北疆大患，国都南悬则指挥不灵，徙都北平，方能居重驭轻、以天子当边冲。所谓「天子守国门」，既强化了九边防御与中央集权，也使京师暴露在边锋之下，土木之变即其代价。岁漕数百万石北运，劳民耗财，然亦促成运河经济带与南北整合。两京并立之制，留都南京保留一套中央机构，既为权宜，亦为后世留下双轨架构。自永乐十九年至清亡，北京作为统一王朝的政治中心沿用近五百年，其城市格局、运河体系与南北重心结构，至今仍有迹可循。",
