    interpretation: "张献忠起义的爆发，是明末政治腐败、财政崩溃与自然灾害叠加的必然产物。三饷加派使赋税远超常年，西北连岁大旱更将边镇军民逼入绝境，所谓「叛民」多为饥卒、驿夫与失业边兵。张献忠以流动作战见长，避实击虚，转战十六年，几覆明室，其成败均源于此。攻破凤阳焚毁皇陵，动摇了朱明王朝的政治合法性；谷城诈降与黄陵城之捷，则暴露明朝剿抚失据、将帅掣肘的痼疾。入蜀建国后，其政权缺乏稳固的经济与政治基础，四面受敌，严刑峻法反而加速自我瓦解。江口沉银与凤凰山之死，为这场起义画上句点；而大西军余部联明抗清，又使其余绪延续于南明历史之中，成为明清鼎革之际承上启下的一环。",
